// Boxing -- an easy-to-miss hidden heap allocation
int number = 42;
object boxed = number;              // BOXES: allocates a new object on the heap
int unboxed = (int)boxed;           // UNBOXES: type-checks and copies the value back out

// Classic boxing trap: non-generic collections box every value type added
ArrayList list = new ArrayList();
list.Add(42);                       // boxes the int -- avoid ArrayList, use List<int>

// IDisposable -- using guarantees Dispose() runs even on exception
public class DbConnection : IDisposable
{
    private SqlConnection _conn;
    public void Dispose() => _conn?.Dispose();
}

using var conn = new DbConnection();
// ... use conn ...
// Dispose() called automatically here, even if an exception was thrown above

// Finalizer as a safety net (rarely needed if IDisposable is used correctly)
public class UnmanagedWrapper : IDisposable
{
    private IntPtr _handle;
    public void Dispose()
    {
        ReleaseHandle();
        GC.SuppressFinalize(this);   // tell GC the finalizer is no longer needed
    }
    ~UnmanagedWrapper() => ReleaseHandle();  // safety net if Dispose() was never called
    private void ReleaseHandle() { /* release _handle */ }
}

// Span<T> -- zero-allocation slicing over existing memory
ReadOnlySpan<char> fullText = "CustomerId=12345;Region=US".AsSpan();
int separatorIndex = fullText.IndexOf(';');
ReadOnlySpan<char> firstField = fullText.Slice(0, separatorIndex);  // no new string allocated
// Compare to: fullText.ToString().Substring(0, separatorIndex) -- allocates a new string

